class ShellCommandValidator:

    ALLOWED_COMMANDS = {
        "npm", "npm.cmd",
        "python", "python3", "python3.10", "python3.11", "python3.12",
        "node", "nodejs",
        "npx", "npx.cmd",
        "echo", "cat", "ls", "touch", "mkdir", "rm", "cp", "mv",
        "chmod", "chown", "bash", "sh", "systemctl", "service",
        "git", "pytest", "sleep", "true", "false",
        "sed", "awk", "grep", "find", "xargs",
        "docker", "docker-compose", "kubectl",
        "make", "cmake", "gcc", "g++",
        "curl", "wget",
    }

    @classmethod
    def validate(cls, command: str) -> tuple[bool, Optional[str]]:
        cleaned = command.strip()
        if not cleaned:
            return False, "Empty command"
        try:
            tokens = shlex.split(cleaned)
        except ValueError as e:
            return False, f"Invalid shell quoting: {e}"
        if not tokens:
            return False, "Empty tokenized command"

        first_token = tokens[0]

        allowed = os.path.exists(first_token) or first_token in cls.ALLOWED_COMMANDS

        forbidden_substrings = {
            ";", "|", "&&", "||", "`", "$(", "${", ">", "<",
        }
        for token in tokens:
            for fragment in forbidden_substrings:
                if fragment in token:
                    return False, f"Forbidden shell pattern in token: {token}"

        if not allowed:
            return False, f"Command not in allowlist: {first_token}"

        return True, None

