class RetryCategory(Enum):
    TRANSIENT = "transient"
    PERMISSION = "permission"
    LOGIC = "logic"


class RetryClassifier:
    @staticmethod
    def classify(task: AtlasTask) -> RetryCategory:
        error_text = (task.error or "").lower()
        output_text = (task.output or "").lower()

        if "timeout" in error_text or task.exit_code == -1:
            return RetryCategory.TRANSIENT
        if "permission" in error_text or "permission denied" in output_text:
            return RetryCategory.PERMISSION
        if "connection" in error_text or "network" in error_text or "unreachable" in output_text:
            return RetryCategory.TRANSIENT
        if "no such file" in error_text or "not found" in error_text:
            return RetryCategory.TRANSIENT
        return RetryCategory.LOGIC

