class WaveStrategy(ExecutionStrategy):
    def __init__(self, executor: WaveExecutor, trace: Optional[TraceContext] = None):
        self.executor = executor
        self.trace = trace

    async def execute(self, tasks: List[AtlasTask]) -> Dict[str, Any]:
        planner = WavePlanner()
        for task in tasks:
            planner.add_task(task)
            self.executor.tasks[task.id] = task
        waves = planner.plan_waves()
        await self.executor.execute_plan(waves)
        execution_uuid = getattr(self.executor, 'execution_uuid', None)
        return _build_execution_report(self.executor, waves, execution_uuid=execution_uuid)

