"""manifest_api.py — API REST automática dos manifests YAML.

Antropofagia do PostgREST do Supabase:
Assim como o Supabase gera API REST automática do schema SQL,
este módulo gera API JSON automática dos manifests YAML do Gran-Mestre.

Uso:
    from native.manifest_api import ManifestAPI

    api = ManifestAPI()
    api.load_all()

    # Listar todos os agentes
    agents = api.agents()

    # Buscar skills por capacidade
    skills = api.filter_skills(capability="security")

    # Query: agentes que suportam COMPLEX
    complex_agents = api.query(type="agent", complexity_max="COMPLEX")
"""

import os
import glob
import json
import yaml
from typing import Optional


class ManifestAPI:
    """API REST-style para consulta de manifests.

    Inspirada no PostgREST do Supabase: auto-descoberta do schema,
    filtros por campo, projeção de colunas.
    """

    def __init__(self, manifests_dir: str = ""):
        if not manifests_dir:
            self.manifests_dir = os.path.expanduser(
                "~/.opencode/skills/gran-mestre/manifests"
            )
        else:
            self.manifests_dir = manifests_dir
        self._entries: list[dict] = []
        self._indexed: bool = False

    def load_all(self) -> list[dict]:
        """Carrega todos os manifests do diretório."""
        self._entries = []
        pattern = os.path.join(self.manifests_dir, "*.yaml")
        for path in glob.glob(pattern):
            try:
                with open(path) as f:
                    data = yaml.safe_load(f)
                if data:
                    data["_path"] = path
                    self._entries.append(data)
            except (yaml.YAMLError, IOError) as e:
                print(f"Erro: {path}: {e}")
        self._indexed = True
        return self._entries

    # --- Métodos Query (como PostgREST) ---

    def agents(self) -> list[dict]:
        """Retorna todos os agentes."""
        return self.query(type="agent")

    def skills(self) -> list[dict]:
        """Retorna todas as skills."""
        return self.query(type="skill")

    def filter_capability(self, capability: str) -> list[dict]:
        """Filtra por capacidade (como ?capability=eq.security)."""
        return [
            e for e in self._entries
            if capability in e.get("capabilities", [])
        ]

    def filter_complexity(self, max_level: str) -> list[dict]:
        """Filtra por nível máximo de complexidade."""
        levels = ["TRIVIAL", "SIMPLE", "MEDIUM", "COMPLEX", "CRITICAL"]
        if max_level not in levels:
            raise ValueError(f"Invalid level: {max_level}")
        max_idx = levels.index(max_level)
        return [
            e for e in self._entries
            if levels.index(e.get("complexity_max", "COMPLEX")) <= max_idx
        ]

    def query(self, **filters) -> list[dict]:
        """Query flexível: query(type="agent", complexity_max="COMPLEX")."""
        results = list(self._entries)
        for key, value in filters.items():
            results = [e for e in results if e.get(key) == value]
        return results

    def select(self, fields: list[str]) -> list[dict]:
        """Projeção de campos (como ?select=name,type)."""
        return [
            {k: v for k, v in e.items() if k in fields}
            for e in self._entries
        ]

    def get(self, name: str) -> Optional[dict]:
        """Busca por nome exato."""
        for e in self._entries:
            if e.get("name") == name:
                return e
        return None

    def search(self, term: str) -> list[dict]:
        """Busca textual em todos os campos."""
        term_lower = term.lower()
        results = []
        for e in self._entries:
            for v in e.values():
                if isinstance(v, str) and term_lower in v.lower():
                    results.append(e)
                    break
                if isinstance(v, list) and any(term_lower in str(item).lower() for item in v):
                    results.append(e)
                    break
        return results

    def stats(self) -> dict:
        """Estatísticas dos manifests carregados."""
        agents = self.agents()
        skills = self.skills()
        all_caps = set()
        for e in self._entries:
            all_caps.update(e.get("capabilities", []))
        return {
            "total": len(self._entries),
            "agents": len(agents),
            "skills": len(skills),
            "unique_capabilities": len(all_caps),
            "capabilities": sorted(all_caps),
        }

    def to_json(self, indent: int = 2) -> str:
        """Exporta todos os manifests como JSON."""
        return json.dumps(self._entries, indent=indent)

    @property
    def loaded(self) -> bool:
        return self._indexed


# Singleton
_default_api = ManifestAPI()


def load_manifests() -> list[dict]:
    """Carrega manifests usando API padrão."""
    return _default_api.load_all()


def query_manifests(**filters) -> list[dict]:
    """Query manifests usando API padrão."""
    if not _default_api.loaded:
        _default_api.load_all()
    return _default_api.query(**filters)

