    def query(self, **filters) -> list[dict]:
        """Query flexível: query(type="agent", complexity_max="COMPLEX")."""
        results = list(self._entries)
        for key, value in filters.items():
            results = [e for e in results if e.get(key) == value]
        return results

    def select(self, fields: list[str]) -> list[dict]:
        """Projeção de campos (como ?select=name,type)."""
        return [
            {k: v for k, v in e.items() if k in fields}
            for e in self._entries
        ]

    def get(self, name: str) -> Optional[dict]:
        """Busca por nome exato."""
        for e in self._entries:
            if e.get("name") == name:
                return e
        return None

    def search(self, term: str) -> list[dict]:
        """Busca textual em todos os campos."""
        term_lower = term.lower()
        results = []
        for e in self._entries:
            for v in e.values():
                if isinstance(v, str) and term_lower in v.lower():
                    results.append(e)
                    break
                if isinstance(v, list) and any(term_lower in str(item).lower() for item in v):
                    results.append(e)
                    break
        return results

    def stats(self) -> dict:
        """Estatísticas dos manifests carregados."""
        agents = self.agents()
        skills = self.skills()
        all_caps = set()
        for e in self._entries:
            all_caps.update(e.get("capabilities", []))
        return {
            "total": len(self._entries),
            "agents": len(agents),
            "skills": len(skills),
            "unique_capabilities": len(all_caps),
            "capabilities": sorted(all_caps),
        }

    def to_json(self, indent: int = 2) -> str:
        """Exporta todos os manifests como JSON."""
        return json.dumps(self._entries, indent=indent)

    @property
    def loaded(self) -> bool:
        return self._indexed


# Singleton
_default_api = ManifestAPI()


def load_manifests() -> list[dict]:
    """Carrega manifests usando API padrão."""
    return _default_api.load_all()


def query_manifests(**filters) -> list[dict]:
    """Query manifests usando API padrão."""
    if not _default_api.loaded:
        _default_api.load_all()
    return _default_api.query(**filters)

