#!/usr/bin/env python3
"""Configura env vars dos MCPs prioritários.

Uso:
    python3 config_mcp_env.py              # Modo interativo
    python3 config_mcp_env.py --show       # Mostrar config atual
    python3 config_mcp_env.py --validate   # Validar config atual

Ctrl+C → Ctrl+V → Ctrl+S → python3 config_mcp_env.py
"""

import json
import os
import sys
from typing import Optional

MCP_CONFIG = os.path.expanduser("~/.opencode/mcp-configs/mcp-servers.json")
ENV_FILE = os.path.expanduser("~/.opencode/.env")

PRIORITY_MCPS = {
    "github": {
        "description": "GitHub API — PRs, issues, repos",
        "env_vars": {
            "GITHUB_PERSONAL_ACCESS_TOKEN": {
                "prompt": "GitHub Personal Access Token",
                "hint": "Crie em: https://github.com/settings/tokens (repo, issues, pull requests)",
                "validate": lambda v: len(v) >= 20,
            }
        },
    },
    "jira": {
        "description": "Jira — tracking de issues",
        "env_vars": {
            "JIRA_URL": {
                "prompt": "Jira URL",
                "hint": "Ex: https://seu-dominio.atlassian.net",
                "validate": lambda v: v.startswith("https://"),
            },
            "JIRA_EMAIL": {
                "prompt": "Jira Email",
                "hint": "Seu email de login no Jira",
                "validate": lambda v: "@" in v,
            },
            "JIRA_API_TOKEN": {
                "prompt": "Jira API Token",
                "hint": "Crie em: https://id.atlassian.com/manage/api-tokens",
                "validate": lambda v: len(v) >= 10,
            },
        },
    },
    "supabase": {
        "description": "Supabase — database, auth, storage",
        "env_vars": {
            "SUPABASE_URL": {
                "prompt": "Supabase Project URL",
                "hint": "Ex: https://xxxxxxxxxxxx.supabase.co (Dashboard > Settings > API)",
                "validate": lambda v: v.startswith("https://") and "supabase" in v,
            },
            "SUPABASE_ANON_KEY": {
                "prompt": "Supabase Anon/Public Key",
                "hint": "Dashboard > Settings > API > anon public key",
                "validate": lambda v: len(v) >= 20,
            },
            "SUPABASE_SERVICE_ROLE_KEY": {
                "prompt": "Supabase Service Role Key (opcional)",
                "hint": "Dashboard > Settings > API > service_role key. Deixe vazio se não usar.",
                "optional": True,
                "validate": lambda v: True,
            },
        },
    },
}


def load_mcp_config() -> dict:
    if not os.path.exists(MCP_CONFIG):
        print(f"❌ MCP config não encontrado: {MCP_CONFIG}")
        sys.exit(1)
    with open(MCP_CONFIG) as f:
        return json.load(f)


def show_current_status():
    """Mostra status atual das env vars."""
    from dotenv import dotenv_values  # type: ignore
    try:
        env = dotenv_values(ENV_FILE) if os.path.exists(ENV_FILE) else {}
    except Exception:
        env = {}

    print("\n📋 Status atual das env vars:")
    print("═" * 60)

    for mcp_name, mcp_info in PRIORITY_MCPS.items():
        print(f"\n  {mcp_name}:")
        for var_name, var_info in mcp_info["env_vars"].items():
            value = env.get(var_name, "")
            if value and not value.startswith("YOUR_"):
                masked = value[:4] + "****" + value[-4:] if len(value) > 8 else "****"
                print(f"    ✅ {var_name}: {masked}")
            else:
                print(f"    ❌ {var_name}: não configurado")


def interactive_setup():
    """Modo interativo para configurar env vars."""
    print("\n🔧 Configuração de MCPs Prioritários")
    print("═" * 60)
    print("Pressione Enter para pular (manter atual)")
    print()

    # Carrega env atual
    env: dict[str, str] = {}
    if os.path.exists(ENV_FILE):
        with open(ENV_FILE) as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith("#") and "=" in line:
                    k, v = line.split("=", 1)
                    env[k.strip()] = v.strip()

    for mcp_name, mcp_info in PRIORITY_MCPS.items():
        print(f"\n📦 {mcp_name} — {mcp_info['description']}")
        print(f"   {'─' * 50}")

        for var_name, var_info in mcp_info["env_vars"].items():
            current = env.get(var_name, "")
            if current and not current.startswith("YOUR_"):
                print(f"   ✅ {var_name} já configurado")
                continue

            print(f"\n   {var_info['prompt']}:")
            print(f"   Dica: {var_info['hint']}")
            value = input(f"   Valor (Enter=pular): ").strip()

            if value:
                if var_info.get("validate", lambda v: True)(value):
                    env[var_name] = value
                    print(f"   ✅ {var_name} salvo")
                else:
                    print(f"   ❌ Valor inválido. Tente novamente.")
                    # Tenta de novo
                    value = input(f"   Valor (Enter=pular): ").strip()
                    if value and var_info.get("validate", lambda v: True)(value):
                        env[var_name] = value
                        print(f"   ✅ {var_name} salvo")
            elif var_info.get("optional"):
                print(f"   ⚪ Pulado (opcional)")
            else:
                print(f"   ⚪ Pulado")

    # Salva
    print("\n💾 Salvando...")
    lines = [
        "# MCP Environment Variables — Configurado por config_mcp_env.py",
        f"# Gerado em: {__import__('datetime').datetime.now().isoformat()}",
        "",
    ]
    for k, v in sorted(env.items()):
        if v:
            lines.append(f"{k}={v}")

    with open(ENV_FILE, "w") as f:
        f.write("\n".join(lines) + "\n")

    # Atualiza mcp-servers.json com project ref do supabase se foi configurado
    if env.get("SUPABASE_URL"):
        ref = env["SUPABASE_URL"].replace("https://", "").split(".")[0]
        update_supabase_ref(ref)

    print(f"✅ Configuração salva em: {ENV_FILE}")

    # Mostra resumo
    configured = sum(1 for v in env.values() if v and not v.startswith("YOUR_"))
    total = sum(len(m["env_vars"]) for m in PRIORITY_MCPS.values())
    print(f"\n📊 Resumo: {configured}/{total} variáveis configuradas")


def update_supabase_ref(ref: str):
    """Atualiza project-ref no MCP supabase."""
    if not os.path.exists(MCP_CONFIG):
        return
    with open(MCP_CONFIG) as f:
        config = json.load(f)

    supabase = config.get("mcpServers", {}).get("supabase", {})
    if supabase:
        args = supabase.get("args", [])
        for i, arg in enumerate(args):
            if arg.startswith("--project-ref="):
                args[i] = f"--project-ref={ref}"
                break
        else:
            args.append(f"--project-ref={ref}")
        with open(MCP_CONFIG, "w") as f:
            json.dump(config, f, indent=2)
        print(f"✅ Supabase project-ref atualizado: {ref}")


def validate_config():
    """Valida configuração atual."""
    if not os.path.exists(ENV_FILE):
        print("❌ .env não encontrado")
        return

    from dotenv import dotenv_values  # type: ignore
    env = dotenv_values(ENV_FILE)

    issues = []
    for mcp_name, mcp_info in PRIORITY_MCPS.items():
        for var_name, var_info in mcp_info["env_vars"].items():
            value = env.get(var_name, "")
            if not value or value.startswith("YOUR_"):
                if not var_info.get("optional"):
                    issues.append(f"❌ {var_name}: não configurado")

    if issues:
        print("\n❌ Problemas encontrados:")
        for i in issues:
            print(f"  {i}")
    else:
        print("\n✅ Todas as variáveis configuradas corretamente!")


def main():
    if "--show" in sys.argv:
        show_current_status()
    elif "--validate" in sys.argv:
        validate_config()
    else:
        interactive_setup()


if __name__ == "__main__":
    main()

